import{_ as e,o as t,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"RAG 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/basics/what-is-rag.md","filePath":"ai/dev/basics/what-is-rag.md"}'),l={name:"ai/dev/basics/what-is-rag.md"};function s(n,a,o,d,h,g){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="rag-是什么" tabindex="-1">RAG 是什么 <a class="header-anchor" href="#rag-是什么" aria-label="Permalink to “RAG 是什么”">​</a></h1><blockquote><p>先检索，再生成。把私有文档切块、向量化、召回相关片段，再交给模型回答——减少胡编，回答能对上来源。</p></blockquote><h2 id="流程-记四步就够" tabindex="-1">流程（记四步就够） <a class="header-anchor" href="#流程-记四步就够" aria-label="Permalink to “流程（记四步就够）”">​</a></h2><ol><li><strong>入库</strong>：文档切块 → 向量化 → 写入向量库/索引</li><li><strong>提问</strong>：用户问题同样向量化</li><li><strong>召回</strong>：找出最相关的若干片段</li><li><strong>生成</strong>：把片段当上下文，再让模型作答（可要求引用出处）</li></ol><h2 id="知识库从哪来" tabindex="-1">知识库从哪来 <a class="header-anchor" href="#知识库从哪来" aria-label="Permalink to “知识库从哪来”">​</a></h2><p>先小后大，先能检索再谈优化。常见来源：</p><ul><li>简历、面试笔记、项目 README</li><li>业务文档、Wiki、接口说明</li><li>会议纪要、规范、FAQ</li></ul><p>不必一上来追求「全公司知识库」；一份 Markdown 目录跑通闭环即可。</p><h2 id="和-agent-的关系" tabindex="-1">和 Agent 的关系 <a class="header-anchor" href="#和-agent-的关系" aria-label="Permalink to “和 Agent 的关系”">​</a></h2><ul><li><strong>RAG</strong>：给模型「可引用的私有知识」</li><li><strong>Agent</strong>：模型 + 工具 + 循环，去「做事」</li></ul><p>Agent 可以把检索当成一个 Tool，但 RAG 本身不是 Agent。概念入门到此即可；落地见 <a href="/my-vitepress-site/ai/dev/agent/">Agent 应用开发</a>。</p><p>选型与场景见 <a href="/my-vitepress-site/ai/explore/model-selection.html">模型选择指南</a>。</p>',12)])])}const _=e(l,[["render",s]]);export{p as __pageData,_ as default};
